// Shared types for the task tracker
export type Priority = 'low' | 'medium' | 'high';

export interface Task {
  id: number;
  title: string;
  priority: Priority;
  done: boolean;
  tags: string[];
  createdAt: Date;
  completedAt?: Date;
}

export interface TaskFilter {
  done?: boolean;
  priority?: Priority;
  tag?: string;
  search?: string;
}

export const PRIORITY_ORDER: Record<Priority, number> = {
  high: 0,
  medium: 1,
  low: 2,
};

import { PRIORITY_ORDER, Priority, Task, TaskFilter } from './types';

export class TaskStore {
  private tasks: Task[] = [];
  private nextId = 1;

  add(title: string, priority: Priority = 'medium', tags: string[] = []): Task {
    const task: Task = {
      id: this.nextId++,
      title: title.trim(),
      priority,
      done: false,
      tags,
      createdAt: new Date(),
    };
    this.tasks.push(task);
    return task;
  }

  complete(id: number): Task {
    const task = this.get(id);
    task.done = true;
    task.completedAt = new Date();
    return task;
  }

  remove(id: number): void {
    this.tasks = this.tasks.filter(task => task.id !== id);
  }

  get(id: number): Task {
    const task = this.tasks.find(candidate => candidate.id === id);
    if (!task) throw new Error(`No task with id ${id}`);
    return task;
  }

  list(filter: TaskFilter = {}): Task[] {
    const search = filter.search?.toLowerCase();
    return this.tasks
      .filter(task => filter.done === undefined || task.done === filter.done)
      .filter(task => !filter.priority || task.priority === filter.priority)
      .filter(task => !filter.tag || task.tags.includes(filter.tag))
      .filter(task => !search || task.title.toLowerCase().includes(search))
      .sort((a, b) => PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority] || a.id - b.id);
  }

  stats() {
    const done = this.tasks.filter(task => task.done).length;
    return { total: this.tasks.length, done, open: this.tasks.length - done };
  }
}

import { Task } from './types';

const ICONS = { high: '!!', medium: '! ', low: '  ' } as const;

export function formatTask(task: Task): string {
  const box = task.done ? '[x]' : '[ ]';
  const tags = task.tags.length ? ` #${task.tags.join(' #')}` : '';
  return `${box} ${ICONS[task.priority]} ${String(task.id).padStart(3)}  ${task.title}${tags}`;
}

export function formatList(tasks: Task[]): string {
  if (tasks.length === 0) return 'Nothing to do. Enjoy your day!';
  return tasks.map(formatTask).join('\n');
}

export function formatStats(stats: { total: number; done: number; open: number }): string {
  const percent = stats.total ? Math.round((stats.done / stats.total) * 100) : 0;
  const bar = '#'.repeat(Math.round(percent / 10)).padEnd(10, '.');
  return `${stats.done}/${stats.total} done [${bar}] ${percent}%`;
}

import { TaskStore } from './store';
import { formatList, formatStats } from './format';

const store = new TaskStore();

store.add('Write the project README', 'medium', ['docs']);
store.add('Fix the login redirect bug', 'high', ['bug', 'auth']);
store.add('Record the CodeVideo demo', 'high', ['video']);
store.add('Upgrade TypeScript', 'low', ['chore']);
store.add('Review open pull requests', 'medium', ['review']);

store.complete(2);
store.complete(4);

console.log('All tasks');
console.log(formatList(store.list()));
console.log();

console.log('Still open, by priority');
console.log(formatList(store.list({ done: false })));
console.log();

console.log('Tagged #video');
console.log(formatList(store.list({ tag: 'video' })));
console.log();

console.log(formatStats(store.stats()));

import assert from 'node:assert/strict';
import { TaskStore } from './store';

const store = new TaskStore();
const readme = store.add('Write the README', 'low', ['docs']);
const bug = store.add('Fix the crash on save', 'high', ['bug']);
store.add('Plan the next sprint');

assert.equal(store.list().length, 3);
assert.deepEqual(store.list().map(task => task.id), [bug.id, 3, readme.id]);

store.complete(bug.id);
assert.equal(store.get(bug.id).done, true);
assert.ok(store.get(bug.id).completedAt instanceof Date);
assert.deepEqual(store.list({ done: false }).map(task => task.title), ['Plan the next sprint', 'Write the README']);

assert.equal(store.list({ tag: 'docs' })[0].id, readme.id);
assert.equal(store.list({ search: 'SPRINT' }).length, 1);

store.remove(readme.id);
assert.deepEqual(store.stats(), { total: 2, done: 1, open: 1 });
assert.throws(() => store.get(readme.id), /No task with id/);

console.log('All task store checks passed');
